  conferir(!(await p.$('[data-dia-csv]')), 'sem botões de planilha/check-in');
  conferir(!(await p.$('#cadForm')), 'sem formulário de cadastro');
  conferir(!(await p.$('[data-chat]')), 'sem bate-papo para visitante');
  const sobrepoe = await p.evaluate(() => { const a = document.querySelector('.help-btn').getBoundingClientRect(), b = document.querySelector('[data-entrar]').getBoundingClientRect(); return a.right > b.left || b.right > innerWidth; });
  conferir(!sobrepoe, '"Como usar" e "Entrar" visíveis sem se sobrepor');
  conferir(!txt.includes('5511958800779') && !txt.includes('11911111111'), 'nenhum WhatsApp de pessoa aparece');
